//*****************************************************************************
// Floor marks: tiles painted on the floor (drawn as flat decals by rc_render.c).
//*****************************************************************************
Mark     rc_mark[RC_MAX_MARKS];
uint16_t rc_nMark;

void rc_MarkTile(int16_t tx, int16_t ty, uint16_t pal, uint16_t life, uint16_t flags)
{
    Mark *m;

    if((uint16_t)tx >= RC_MAP_W || (uint16_t)ty >= RC_MAP_H || Solid(tx, ty)) return;
    if(rc_nMark >= RC_MAX_MARKS) return;
    m = &rc_mark[rc_nMark++];
    m->tx = (uint16_t)tx;  m->ty = (uint16_t)ty;
    m->pal = pal;  m->life = life;  m->flags = flags;
}


// Mark every tile along a straight line (half-tile steps).
void rc_MarkLine(int32_t x0, int32_t y0, int32_t x1, int32_t y1, uint16_t pal, uint16_t life)
{
    int16_t dx = RD(x1 - x0), dy = RD(y1 - y0), n = (int16_t)(Dist10(dx, dy) / 512 + 1), i;
    int16_t lx = -1, ly = -1;

    for(i = 0; i <= n; i++)
    {
        int16_t tx = (int16_t)((x0 + ((int32_t)dx * i) / n) >> 10);
        int16_t ty = (int16_t)((y0 + ((int32_t)dy * i) / n) >> 10);
        if(tx != lx || ty != ly) rc_MarkTile(tx, ty, pal, life, 0);
        lx = tx; ly = ty;
    }
}


void rc_MarksClear(void)
{
    rc_nMark = 0;
}


// Distance (Q10) from point p to segment a-b.
static int16_t SegDist(int32_t px, int32_t py, int32_t ax, int32_t ay, int32_t bx, int32_t by)
{
    int32_t vx = bx - ax, vy = by - ay, wx = px - ax, wy = py - ay;
    int32_t vv = (vx >> 4) * (vx >> 4) + (vy >> 4) * (vy >> 4);
    int32_t t  = (vv > 0) ? (((wx >> 4) * (vx >> 4) + (wy >> 4) * (vy >> 4)) << 8) / vv : 0;   // Q8

    if(t < 0) t = 0;
    if(t > 256) t = 256;
    return DistP(px, py, ax + ((vx * t) >> 8), ay + ((vy * t) >> 8));
}


//*****************************************************************************
// The Earth Golem's door seal: stone walls rise in every open doorway of the
// chamber it shares with the player; they crumble after 10 s (cracking near the
// end), at once if the player escapes the chamber or the Golem dies.
//*****************************************************************************
#define SEAL_MAX     16
#define SEAL_FRAMES  300
static uint16_t s_seal[SEAL_MAX], s_nSeal, s_sealT, s_sealRoom;

static bool IsDoorChar(char ch)
{
    return (ch >= '1' && ch <= '8') || ch == 'D' || ch == 's' || ch == 'x';
}


// Open doorway cells on the ring just outside room r. Returns how many.
static uint16_t FindDoorways(uint16_t r, uint16_t *out)
{
    const RoomDef *d = &rc_kRoom[r];
    int16_t  x, y, n = 0;

    for(y = (int16_t)(d->y0 - 1); y <= (int16_t)(d->y1 + 1); y++)
        for(x = (int16_t)(d->x0 - 1); x <= (int16_t)(d->x1 + 1); x++)
        {
            uint16_t cell;
            bool     edge = (x == (int16_t)d->x0 - 1 || x == (int16_t)d->x1 + 1 ||
                             y == (int16_t)d->y0 - 1 || y == (int16_t)d->y1 + 1);

            if(!edge || (uint16_t)x >= RC_MAP_W || (uint16_t)y >= RC_MAP_H) continue;
            cell = (uint16_t)(((uint16_t)y << RC_MAP_SHIFT) + (uint16_t)x);
            if(rc_tile[cell] != 0u || !IsDoorChar(rc_MapCh((uint16_t)x, (uint16_t)y))) continue;
            if(DistP(TILE_C(x), TILE_C(y), rc_px, rc_py) < 1600) return 0;    // player in a doorway: no seal
            if(n < SEAL_MAX) out[n++] = cell;
        }
    return (uint16_t)n;
}


static void BreakSeal(void)
{
    uint16_t i;

    for(i = 0; i < s_nSeal; i++) rc_tile[s_seal[i]] = 0;
    if(s_nSeal) { rc_flowTx = -1; rc_viewDirty = 2; rc_Sfx(&sfx_explosion); }
    s_nSeal = 0;
    s_sealT = 0;
}


//*****************************************************************************
// The Elemental Golem (rc.md 14.6). Forms in order Earth, Fire, Ice, Lightning,
// three attacks each. Form colour = body colour = floor-mark colour.
//*****************************************************************************
enum { GF_EARTH, GF_FIRE, GF_ICE, GF_LIGHT };
enum { GA_THROW, GA_SLAM, GA_SEAL, GA_LAVA, GA_ICE, GA_DASH };
static const uint16_t kGolemSeq[4][3] =
{
    { GA_THROW, GA_SEAL,  GA_SLAM  },      // Earth: rocks, door seal, ground slam
    { GA_THROW, GA_LAVA,  GA_THROW },      // Fire: lava bolts, lava ring
    { GA_ICE,   GA_THROW, GA_ICE   },      // Ice: spike cross, ice bolts
    { GA_DASH,  GA_DASH,  GA_DASH  },      // Lightning: teleport-slash triangles
};
static const uint16_t kGolemMark[4] = { PT_MARK_EARTH, PT_PUDDLE_FIRE, PT_MARK_WHITE, PT_MARK_BLUE };
static const uint16_t kGolemBolt[4] = { BK_ROCK, BK_FIREBALL, BK_ICE, BK_SPARK };
static int32_t s_triX[3], s_triY[3];      // Lightning: the triangle's corners (Golem, A, B)

#define WARN_FRAMES  30                    // ~1 s warning (rc.md 14.6, tunable)
#define LAVA_FRAMES  150

// Paint the ice cross: N, E, S, W from the Golem's tile to the walls.
static void IceCross(const Enemy *e, uint16_t pal, uint16_t life, uint16_t flags)
{
    int16_t gx = (int16_t)(e->x >> 10), gy = (int16_t)(e->y >> 10), k, t;

    for(k = 0; k < 4; k++)
        for(t = 1; t < 24; t++)
        {
            int16_t x = (int16_t)(gx + rc_kNbDx[k] * t), y = (int16_t)(gy + rc_kNbDy[k] * t);
            if(Solid(x, y)) break;
            rc_MarkTile(x, y, pal, life, flags);
        }
}


static void LavaRing(int16_t cx, int16_t cy, uint16_t life, uint16_t flags)
{
    uint16_t a;

    for(a = 0; a < RC_ANGLES; a += 48u)        // tiles on a circle of radius 3
        rc_MarkTile((int16_t)((TILE_C(cx) + (((int32_t)COS(a) * 3072L) >> 14)) >> 10),
                    (int16_t)((TILE_C(cy) + (((int32_t)SIN(a) * 3072L) >> 14)) >> 10),
                    PT_PUDDLE_FIRE, life, flags);
}


static void GolemWindup(Enemy *e, uint16_t atk, uint16_t form)
{
    uint16_t pal = kGolemMark[form], cells[SEAL_MAX], n, i;
    int16_t  gx = (int16_t)(e->x >> 10), gy = (int16_t)(e->y >> 10), x, y;

    e->aux2 = atk;
    e->st   = 1;
    e->tm   = (atk == GA_THROW) ? 18u : WARN_FRAMES;
    switch(atk)
    {
        case GA_SLAM:                                   // 5 x 5 around the Golem
            for(y = -2; y <= 2; y++) for(x = -2; x <= 2; x++)
                if(Abs16(x) + Abs16(y) < 4) rc_MarkTile((int16_t)(gx + x), (int16_t)(gy + y), pal, WARN_FRAMES, 0);
            break;
        case GA_SEAL:
            n = (s_nSeal == 0u && rc_playerRoom == rc_RoomAt(e->x, e->y) && rc_playerRoom != RM_NONE)
                ? FindDoorways(rc_playerRoom, cells) : 0u;
            if(n == 0u) { GolemWindup(e, GA_SLAM, form); return; }     // nothing to seal: slam instead
            for(i = 0; i < n; i++)
                rc_MarkTile((int16_t)(cells[i] & (RC_MAP_W - 1u)), (int16_t)(cells[i] >> RC_MAP_SHIFT), pal, WARN_FRAMES, MK_WALL);
            break;
        case GA_LAVA:
            e->tx = (int16_t)((gx << 8) | (gy & 0xFF));            // remember the ring's centre
            LavaRing(gx, gy, WARN_FRAMES, 0);
            break;
        case GA_ICE:
            IceCross(e, PT_MARK_WHITE, WARN_FRAMES, 0);
            break;
        case GA_DASH:                                   // a blue triangle: Golem -> A (player) -> B -> Golem
        {
            int16_t dx = RD(rc_px - e->x), dy = RD(rc_py - e->y), d = Dist10(dx, dy);

            if(d < 1) d = 1;
            s_triX[0] = e->x;   s_triY[0] = e->y;
            s_triX[1] = rc_px;  s_triY[1] = rc_py;
            s_triX[2] = rc_px - ((int32_t)dy * 2600L) / d + ((int32_t)dx * -1200L) / d;   // off to one side
            s_triY[2] = rc_py + ((int32_t)dx * 2600L) / d + ((int32_t)dy * -1200L) / d;
            if(Blocked(s_triX[2], s_triY[2], 200)) { s_triX[2] = (e->x + rc_px) >> 1; s_triY[2] = (e->y + rc_py) >> 1; }
            for(i = 0; i < 3u; i++)
                rc_MarkLine(s_triX[i], s_triY[i], s_triX[(i + 1u) % 3u], s_triY[(i + 1u) % 3u], pal, WARN_FRAMES + 6u);
            e->tm = WARN_FRAMES + 6u;
            break;
        }
        default: break;                                 // throws need no floor mark
    }
    rc_SfxSoft(&sfx_laser);
}


static void GolemStrike(Enemy *e, uint16_t form, int16_t dist)
{
    uint16_t i;

    switch(e->aux2)
    {
        case GA_THROW:
            for(i = 0; i < 3u; i++) rc_ShootBolt(e, (int16_t)((int16_t)i * 30 - 30), kGolemBolt[form], 70, 120);
            break;
        case GA_SLAM:
            if(dist < 2300) rc_HurtPlayer(DMG_BOSS_HEAVY);
            rc_AddSpark(e->x, e->y, 2, 24, PT_PUFF_FIRE, 10);
            rc_Sfx(&sfx_explosion);
            break;
        case GA_SEAL:
            s_nSeal = FindDoorways(rc_playerRoom, s_seal);
            for(i = 0; i < s_nSeal; i++) rc_tile[s_seal[i]] = TILE_EARTH;
            s_sealT = SEAL_FRAMES;
            s_sealRoom = rc_playerRoom;
            rc_flowTx = -1;
            rc_viewDirty = 2;
            rc_Sfx(&sfx_explosion);
            break;
        case GA_LAVA:                                   // the ring burns for 5 s (marks stay lit)
            LavaRing((int16_t)((uint16_t)e->tx >> 8), (int16_t)(e->tx & 0xFF), LAVA_FRAMES, MK_STEADY);
            e->ty = LAVA_FRAMES;
            break;
        case GA_ICE:                                    // spikes burst from the white tiles
        {
            int16_t px = (int16_t)(rc_px >> 10), py = (int16_t)(rc_py >> 10), gx = (int16_t)(e->x >> 10), gy = (int16_t)(e->y >> 10);
            bool    hit = false;

            if(px == gx || py == gy)                    // on the Golem's row or column, nothing in between?
            {
                int16_t sx = (px > gx) ? 1 : (px < gx) ? -1 : 0, sy = (py > gy) ? 1 : (py < gy) ? -1 : 0, x = gx, y = gy;
                hit = true;
                while(x != px || y != py) { x = (int16_t)(x + sx); y = (int16_t)(y + sy); if(Solid(x, y)) { hit = false; break; } }
            }
            IceCross(e, PT_SPIKE, 24, MK_SPIKE | MK_STEADY);
            if(hit) { rc_HurtPlayer(DMG_BOSS); rc_pSlow = 60; }
            rc_Sfx(&sfx_explosion);
            break;
        }
        default:                                        // GA_DASH: rush along all three lanes
            for(i = 0; i < 3u; i++)
            {
                if(SegDist(rc_px, rc_py, s_triX[i], s_triY[i], s_triX[(i + 1u) % 3u], s_triY[(i + 1u) % 3u]) < 600)
                { rc_HurtPlayer(DMG_BOSS); break; }     // the slash hurts the player only (rc.md 14.6)
                rc_AddSpark(s_triX[i], s_triY[i], 8, 12, PT_ORB_BOLT, 8);
            }
            rc_Sfx(&sfx_staff_storm);
            break;
    }
}


static bool ThinkGolem(Enemy *e, int16_t sp, int16_t dx, int16_t dy, int16_t dist)
{
    uint16_t form = e->cnt & 3u, step = (uint16_t)((e->cnt >> 2) & 3u);

    if(e->ty > 0)                                       // lava ring burning: hurts inside the band
    {
        int16_t lx = (int16_t)((uint16_t)e->tx >> 8), ly = (int16_t)(e->tx & 0xFF);
        int16_t d = DistP(TILE_C(lx), TILE_C(ly), rc_px, rc_py);

        e->ty--;
        if((e->ty % 15) == 0 && d > 2400 && d < 3800) rc_HurtPlayer(DMG_SMALL);
    }

    switch(e->st)
    {
        case 0:                                         // walk toward the player
            if(dist > 1600) rc_Chase(e, sp, 0, dx, dy, dist);
            if(e->tm) { e->tm--; break; }
            GolemWindup(e, kGolemSeq[form][step], form);
            break;
        case 1:                                         // wind-up: pose held, marks flashing
            if(--e->tm == 0u)
            {
                GolemStrike(e, form, dist);
                e->st = 2;
                e->tm = 30;
            }
            break;
        default:                                        // recover, then the next attack / form
            if(--e->tm == 0u)
            {
                if(++step >= 3u) { step = 0; form = (uint16_t)((form + 1u) & 3u); }
                e->cnt = (uint16_t)((e->cnt & ~0xFu) | (step << 2) | form);
                e->st = 0;
                e->tm = (uint16_t)(40u + RAND(30));
            }
            break;
    }
    return e->st != 1u || e->aux2 != GA_DASH;
}


//*****************************************************************************
// The Beholder (rc.md 14.3): hovers, teleports, fires fast aimed bolts, and two
// beams that track the player: spell-disable (green) and confusion (blue).
//*****************************************************************************
static bool ThinkEye(Enemy *e, int16_t sp, int16_t dx, int16_t dy, int16_t dist)
{
    switch(e->st)
    {
        case 0:
            rc_KeepRange(e, sp, 3200, 4800, rc_SgnOf(e), dx, dy, dist);
            if(++e->aux >= 240u) { e->aux = 0; (void)rc_TeleportEnemy(e, rc_px, rc_py, 3000, 5000); }
            if(e->tm) { e->tm--; break; }
            e->aux2 = (uint16_t)((e->aux2 + 1u + RAND(2)) % 3u);     // 0 bolts, 1 spell-disable, 2 confusion
            e->st = 1;
            e->tm = 30;
            break;
        case 1:                                         // wind-up: the eye glows; beams draw their line
            if(e->aux2 && (e->tm % 8u) == 0u)          // re-drawn every 8 frames so the line tracks the player
                rc_MarkLine(e->x, e->y, rc_px, rc_py, (e->aux2 == 1u) ? PT_MARK_GREEN : PT_MARK_BLUE, 8);
            if(--e->tm) break;
            if(e->aux2 == 0u)
            {
                rc_ShootBolt(e, -20, BK_ORB, 100, 100);
                rc_ShootBolt(e,   0, BK_ORB, 100, 100);
                rc_ShootBolt(e,  20, BK_ORB, 100, 100);
            }
            else if(rc_CanSee(e->x, e->y, rc_px, rc_py))
            {
                if(e->aux2 == 1u) rc_silence = 75; else rc_confuse = 75;     // ~2.5 s
                rc_AddSpark(rc_px, rc_py, 6, 10, PT_PUFF_ARCANE, 8);
                rc_hud |= HUD_HINT;
            }
            rc_SfxSoft(&sfx_laser);
            e->st = 2;
            e->tm = 20;
            break;
        default:
            if(--e->tm == 0u) { e->st = 0; e->tm = (uint16_t)(70u + RAND(40)); }
            break;
    }
    return true;
}


//*****************************************************************************
// The Slime King (rc.md 14.4): bounces, lobs globs that leave puddles, rains
// acid; at 2/3 and 1/3 health it splits into three slimes and reforms only when
// they are all dead (hidden and untouchable meanwhile).
//*****************************************************************************
#define SK_HIDDEN  9u

static bool ThinkSlimeKing(Enemy *e, int16_t sp, int16_t dx, int16_t dy, int16_t dist)
{
    uint16_t k;

    if(e->st == SK_HIDDEN)                              // split: wait for the pieces to die
    {
        if(rc_SummonCount(ET_SLIME_S) == 0u) { e->st = 0; e->tm = 40; rc_Toast("The Slime King reforms!", NULL); }
        return false;
    }
    for(k = 0; k < 2u; k++)                             // thresholds: 2/3 and 1/3 health
        if(!(e->cnt & (0x100u << k)) && (int32_t)e->hp * 3L < (int32_t)e->mhp * (int32_t)(2u - k))
        {
            e->cnt |= (uint16_t)(0x100u << k);
            rc_SummonAround(e, ET_SLIME_S, 3);
            e->st = SK_HIDDEN;
            rc_AddSpark(e->x, e->y, 2, 24, PT_PUDDLE_SLIME, 12);
            return false;
        }

    switch(e->st)
    {
        case 0:
            rc_Chase(e, sp, 0, dx, dy, dist);
            if(e->tm) { e->tm--; break; }
            switch((e->cnt++) % 3u)
            {
                case 0:  for(k = 0; k < 3u; k++) rc_ShootBolt(e, (int16_t)((int16_t)k * 40 - 40), BK_GLOB, 45, 70);   // glob lob
                         e->st = 4; e->tm = 30; break;
                case 1:  for(k = 0; k < 4u; k++)                                        // acid rain
                         {
                             int32_t rx = rc_px + (int32_t)RAND(3600) - 1800L, ry = rc_py + (int32_t)RAND(3600) - 1800L;
                             if(!Blocked(rx, ry, 100)) rc_MakeWarn(rx, ry, 650, WARN_FRAMES, AR_SLIME, 170);
                         }
                         e->st = 4; e->tm = 40; break;
                default: e->st = 2; e->tm = 24; break;                                  // royal bounce
            }
            break;
        case 2:
            if(--e->tm == 0u) { rc_AimCharge(e, sp, dx, dy); e->st = 3; e->tm = 16; }
            break;
        case 3:
            if(!rc_ChargeStep(e) || --e->tm == 0u) { e->st = 4; e->tm = 30; }
            break;
        default:
            if(--e->tm == 0u) { e->st = 0; e->tm = (uint16_t)(70u + RAND(40)); }
            break;
    }
    return true;
}


//*****************************************************************************
// The Lich Lord (rc.md 14.5). Phase 1 keeps its distance, fires green death
// bolts and Soul Drain (heals it), and keeps up to 4 skeletons raised (mostly
// melee). Phase 2 (half health) charges straight at the player. On death it
// detonates after a visible and audible warning (rc_OnBossDeath).
//*****************************************************************************
static bool ThinkLich(Enemy *e, int16_t sp, int16_t dx, int16_t dy, int16_t dist)
{
    bool p2 = ((int32_t)e->hp * 2L < (int32_t)e->mhp);

    switch(e->st)
    {
        case 0:
            if(p2) rc_Chase(e, (int16_t)(sp + (sp >> 1)), 0, dx, dy, dist);
            else   rc_KeepRange(e, sp, 3200, 4800, rc_SgnOf(e), dx, dy, dist);
            if(!p2 && ++e->aux >= 150u)
            {
                e->aux = 0;
                if(rc_SummonCount(ET_SKELETON) + rc_SummonCount(ET_ARCHER) < 4u)
                    rc_SummonAround(e, (RAND(4) == 0u) ? ET_ARCHER : ET_SKELETON, 1u);
            }
            if(++e->aux2 >= (p2 ? 55u : 75u))
            {
                e->aux2 = 0;
                rc_ShootBolt(e, 0, ((++e->cnt % 3u) == 0u) ? BK_DRAIN : BK_DEATH, 64, 130);
                rc_SfxSoft(&sfx_laser);
            }
            if(e->tm) { e->tm--; break; }
            if(p2) { e->st = 1; e->tm = 20; }           // phase 2: charge wind-up (eyes flare)
            else e->tm = 60;
            break;
        case 1:
            if(--e->tm == 0u) { rc_AimCharge(e, sp, dx, dy); e->st = 2; e->tm = 18; }
            break;
        case 2:
            if(!rc_ChargeStep(e) || --e->tm == 0u) { e->st = 3; e->tm = 30; }
            break;
        default:
            if(--e->tm == 0u) { e->st = 0; e->tm = (uint16_t)(70u + RAND(50)); }
            break;
    }
    return true;
}


//*****************************************************************************
// The Vampire Lord (rc.md 14.7): heavy damage or a close player turns it into a
// bat (still hittable) that scatters and reforms elsewhere. Telegraphed blood
// bolt heals it on a hit. Keeps a few bats around, with a bigger swarm now and then.
//*****************************************************************************
#define VL_BAT  5u

static bool ThinkVampire(Enemy *e, int16_t sp, int16_t dx, int16_t dy, int16_t dist)
{
    if(++e->aux >= 60u) { e->aux = 0; e->tx = e->hp; }           // damage taken in the last 2 s
    if(e->st != VL_BAT && (e->tx - e->hp > e->mhp / 5 || dist < 1300))
    {
        e->st = VL_BAT;
        e->tm = 90;
        rc_AddSpark(e->x, e->y, 6, 14, PT_ORB_BLOOD, 8);
    }

    switch(e->st)
    {
        case 0:
            rc_KeepRange(e, sp, 2600, 3800, rc_SgnOf(e), dx, dy, dist);
            if(e->tm) { e->tm--; break; }
            if((++e->cnt % 4u) == 0u && rc_SummonCount(ET_BAT) < 3u) rc_SummonAround(e, ET_BAT, 5);   // a swarm
            else if(rc_SummonCount(ET_BAT) < 3u) rc_SummonAround(e, ET_BAT, 1);                       // keep a few
            e->st = 1;
            e->tm = 24;                                 // blood bolt wind-up (the Lord glows)
            break;
        case 1:
            if(--e->tm) break;
            rc_ShootBolt(e, 0, BK_DRAIN, 80, 120);
            rc_SfxSoft(&sfx_laser);
            e->st = 2;
            e->tm = 40;
            break;
        case VL_BAT:                                    // bat form: flee and weave, then reform elsewhere
        {
            int16_t d = dist ? dist : 1;
            rc_Slide(e, (int16_t)(((int32_t)-dx * (sp * 2)) / d + (int16_t)RAND(21) - 10),
                        (int16_t)(((int32_t)-dy * (sp * 2)) / d + (int16_t)RAND(21) - 10));
        }
            if(--e->tm == 0u)
            {
                (void)rc_TeleportEnemy(e, rc_px, rc_py, 3000, 5000);
                e->st = 0; e->tm = 30; e->tx = e->hp;
            }
            return false;
        default:
            if(--e->tm == 0u) { e->st = 0; e->tm = (uint16_t)(50u + RAND(40)); }
            break;
    }
    return true;
}


//*****************************************************************************
// The Ancient Dragon (rc.md 15). Three phases (2/3, 1/3 health) add attacks and
// speed. Every melee attack is marked on the floor first.
//*****************************************************************************
// Attacks. Phase 1 picks from the first five, phase 2 adds the tail sweep, phase 3 the inferno.
enum { DA_BREATH, DA_CLAW, DA_FIREBALL, DA_CHARGE, DA_SLAM, DA_TAIL, DA_INFERNO };
#define DRAGON_COMBO     3u                     // attacks before it tires and lands
#define DRAGON_EXPOSE    120u                   // frames the weak spot stays open (4 s, less when enraged)
#define DR_DASH          4u                     // state: charging along its lane
#define DASH_SPEED       50                     // rc_AimCharge speed: 200 Q10 a frame (6 tiles a second)
#define DASH_FRAMES      40u
#define SLAM_UP          50u                    // sky slam: frames from take-off to landing
#define SLAM_MARK        22u                    //   the landing ring appears this many frames before
#define SLAM_R           1500                   //   landing radius (1.5 tiles)

// Aim a charge at the player and burn its lane into the floor (the telegraph is honest:
// the dash follows exactly this line).
static void DragonAimDash(Enemy *e, int16_t dx, int16_t dy, uint16_t warn)
{
    rc_AimCharge(e, DASH_SPEED, dx, dy);
    rc_MarkLine(e->x, e->y, e->x + (int32_t)e->tx * DASH_FRAMES, e->y + (int32_t)e->ty * DASH_FRAMES,
                PT_PUDDLE_FIRE, (uint16_t)(warn + DASH_FRAMES));
    e->st  = 1;
    e->tm  = warn;
    e->aux2 = DA_CHARGE;
    rc_Sfx(&sfx_game_over);                             // the roar before the run
}

// Fight loop: a combo of telegraphed attacks (scales: half damage), then it lands
// exhausted with its chest core blazing (weak spot: double damage, rc_PlayerHit),
// then it roars back up. A charge that slams into a wall or pillar stuns it and
// exposes the core at once. Each phase (2/3, 1/3 health) adds an attack, speeds it
// up, and opens with a roar.
//   e->cnt: phase (high byte), attacks in this combo (low byte)
//   e->aux: the current charge has hit the player (bit 0), extra charges done (bits 1+)
//   e->tx/ty: dash velocity, or the sky slam's landing spot (Q10 >> 4)
static bool ThinkDragon(Enemy *e, int16_t sp, int16_t dx, int16_t dy, int16_t dist)
{
    uint16_t p = rc_Phase(e), k;

    if(p > (e->cnt >> 8) && e->st != DR_DASH && e->st != 1u)  // a new phase: roar, enrage
    {
        e->cnt = (uint16_t)((e->cnt & 0xFFu) | (p << 8));
        rc_Toast(p == 2u ? "The Dragon is furious!" : "The Dragon is enraged!", NULL);
        rc_Sfx(&sfx_game_over);
        e->st = 2;
        e->tm = 45;
    }
    if(p) sp = (int16_t)(sp + (sp >> 2));

    switch(e->st)
    {
        case 0:
            if(dist > 2400) rc_Chase(e, sp, 0, dx, dy, dist);
            if(e->tm) { e->tm--; break; }
            if((e->cnt & 0xFFu) >= DRAGON_COMBO)        // tired: land, expose the weak spot
            {
                e->cnt &= 0xFF00u;
                e->st = DR_EXPOSED;
                e->tm = (uint16_t)(DRAGON_EXPOSE - 20u * p);
                rc_Toast("WEAK SPOT! Hit the glowing core!", NULL);
                rc_Sfx(&sfx_powerup);
                break;
            }
            e->aux2 = RAND(5u + p);
            if(dist > 4500 && RAND(2)) e->aux2 = DA_CHARGE + RAND(2);   // far away: it comes to you
            e->st = 1;
            switch(e->aux2)
            {
                case DA_CLAW:                           // 3 tiles in front, toward the player
                    rc_MarkLine(e->x, e->y, e->x + ((int32_t)dx * 2400L) / (dist ? dist : 1),
                                e->y + ((int32_t)dy * 2400L) / (dist ? dist : 1), PT_PUDDLE_FIRE, 24);
                    e->tm = 24; break;
                case DA_CHARGE:
                    e->aux = 0;
                    DragonAimDash(e, dx, dy, (uint16_t)(36u - 6u * p));
                    break;
                case DA_SLAM:                           // takes to the sky (rc_DragonPose lifts it)
                    e->tm = SLAM_UP;
                    rc_SfxSoft(&sfx_powerup);
                    break;
                case DA_TAIL:                           // a ring around it
                    for(k = 0; k < RC_ANGLES; k += 64u)
                        rc_MarkTile((int16_t)((e->x + (((int32_t)COS(k) * 2048L) >> 14)) >> 10),
                                    (int16_t)((e->y + (((int32_t)SIN(k) * 2048L) >> 14)) >> 10), PT_PUDDLE_FIRE, 36, 0);
                    e->tm = 36; break;
                case DA_INFERNO:                        // lava patches around the player (they warn themselves)
                    rc_MakeWarn(rc_px, rc_py, 900, 40, AR_FIRE, 150);
                    rc_MakeWarn(rc_px + 1500L, rc_py - 700L, 900, 40, AR_FIRE, 150);
                    rc_MakeWarn(rc_px - 1300L, rc_py + 900L, 900, 40, AR_FIRE, 150);
                    rc_MakeWarn(rc_px + 600L, rc_py + 1600L, 900, 50, AR_FIRE, 150);
                    e->tm = 40; break;
                default: e->tm = 30; break;             // breath / fireball: the pose warns
            }
            break;

        case 1:
            if(e->aux2 == DA_SLAM && e->tm == SLAM_MARK)            // high above: mark where it lands
            {
                e->tx = (int16_t)(rc_px >> 4);
                e->ty = (int16_t)(rc_py >> 4);
                rc_MakeWarn(rc_px, rc_py, SLAM_R, SLAM_MARK, AR_FIRE, 90);
            }
            if(--e->tm) break;
            switch(e->aux2)
            {
                case DA_BREATH:                         // a fan of flame from the mouth
                    for(k = 0; k < (p ? 5u : 3u); k++) rc_ShootBolt(e, (int16_t)((int16_t)k * 20 - (p ? 40 : 20)), BK_FLAME, 68, 115);
                    break;
                case DA_CLAW:
                    if(dist < 2600) rc_HurtPlayer(DMG_BOSS_HEAVY);
                    break;
                case DA_FIREBALL:
                    rc_ShootBolt(e, -25, BK_FIREBALL, 50, 140);
                    rc_ShootBolt(e,  25, BK_FIREBALL, 50, 140);
                    if(p == 2u) rc_ShootBolt(e, 0, BK_FIREBALL, 60, 140);
                    break;
                case DA_CHARGE:                         // the run itself
                    e->st = DR_DASH;
                    e->tm = DASH_FRAMES;
                    e->aux &= ~1u;
                    return false;
                case DA_SLAM:                           // lands: a crushing blow and a fire shockwave
                {
                    int32_t lx = (int32_t)e->tx << 4, ly = (int32_t)e->ty << 4;

                    if(!Blocked(lx, ly, 230)) { e->x = lx; e->y = ly; }
                    if(DistP(rc_px, rc_py, e->x, e->y) < SLAM_R) rc_HurtPlayer(DMG_BOSS_HEAVY);
                    rc_MakeWave(e->x, e->y, 70, 4200, WV_FIRE);
                    rc_AddSpark(e->x, e->y, 0, 70, PT_PUFF_FIRE, 16);
                    break;
                }
                case DA_TAIL:
                    if(dist < 2700) rc_HurtPlayer(DMG_BOSS_HEAVY);
                    break;
                default: break;
            }
            rc_SfxSoft(&sfx_laser);
            e->cnt++;                                   // one more attack in this combo
            e->st = 2;
            e->tm = 30;
            break;

        case DR_DASH:
            if(!rc_ChargeStep(e))                       // slammed into a wall or pillar: stunned
            {
                rc_Sfx(&sfx_explosion);
                rc_AddSpark(e->x, e->y, 4, 60, PT_ROCK, 14);
                rc_Toast("It crashed! Hit the core!", NULL);
                e->cnt &= 0xFF00u;
                e->st = DR_EXPOSED;
                e->tm = (uint16_t)(DRAGON_EXPOSE + 30u - 20u * p);
                break;
            }
            if(!(e->aux & 1u) && dist < 1100)           // trampled
            {
                e->aux |= 1u;
                rc_HurtPlayer(DMG_BOSS_HEAVY);
                rc_PlayerPush((int16_t)(e->tx * 3), (int16_t)(e->ty * 3));
            }
            if(--e->tm) break;
            if((e->aux >> 1) < p)                       // enraged: turns and charges again
            {
                e->aux = (uint16_t)((e->aux + 2u) & ~1u);
                DragonAimDash(e, dx, dy, 18);
                break;
            }
            e->cnt++;
            e->st = 2;
            e->tm = 30;
            break;

        case DR_EXPOSED:                                // landed and panting: no attacks
            if(--e->tm == 0u) { e->st = 2; e->tm = 30; rc_Sfx(&sfx_game_over); }   // roars back up
            break;

        default:
            if(--e->tm == 0u) { e->st = 0; e->tm = (uint16_t)(45u - 10u * p + RAND(25)); }
            break;
    }
    return false;                                       // the Dragon hurts with its attacks, not its touch
}


// High in the sky during a sky slam (beams pass beneath it).
static bool DragonAloft(const Enemy *e)
{
    return e->st == 1u && e->aux2 == DA_SLAM && e->tm < SLAM_UP - 12u;
}


// How the Dragon's parts look right now (rc_render.c draws body, two wings, head).
// lift raises the whole Dragon (the sky slam flies it off the top of the view).
void rc_DragonPose(const Enemy *e, uint16_t *head, int16_t *headZ, uint16_t *pal, uint16_t *wing, int16_t *lift)
{
    bool windup = (e->st == 1u), roar = (e->st == 2u && e->tm > 30u), dash = (e->st == DR_DASH);
    bool slam = windup && e->aux2 == DA_SLAM;

    *pal   = (e->st == DR_EXPOSED) ? PT_DRAGON_CORE :
             (dash || (windup && (e->aux2 == DA_BREATH || e->aux2 == DA_FIREBALL))) ? PT_DRAGON_HOT : PT_DRAGON;
    *head  = (windup || roar || dash) ? SH_DRAGON_ROAR : SH_DRAGON_HEAD;
    *headZ = (e->st == DR_EXPOSED) ? 14 : dash ? 20 : 27;      // exposed: the head hangs low; dash: head down
    *wing  = (e->st == DR_EXPOSED) ? SH_WING_DOWN : dash ? SH_WING_UP :
             (((rc_portalPhase >> ((windup || slam) ? 1 : 3)) & 1u) ? SH_WING_UP : SH_WING_DOWN);
    *lift  = !slam ? 0 : (e->tm > SLAM_MARK) ? (int16_t)(3u * (SLAM_UP - e->tm)) : 90;
}


//*****************************************************************************
// Dispatch, looks, per-tick upkeep, deaths
//*****************************************************************************
bool rc_ThinkBoss(Enemy *e, int16_t sp, int16_t dx, int16_t dy, int16_t dist)
{
    switch(e->type)
    {
        case ET_GOLEM:     return ThinkGolem(e, sp, dx, dy, dist);
        case ET_EYEKING:   return ThinkEye(e, sp, dx, dy, dist);
        case ET_SLIMEKING: return ThinkSlimeKing(e, sp, dx, dy, dist);
        case ET_LICH:      return ThinkLich(e, sp, dx, dy, dist);
        case ET_VAMPIRE:   return ThinkVampire(e, sp, dx, dy, dist);
        default:           return ThinkDragon(e, sp, dx, dy, dist);
    }
}


// Which sprite / palette a boss shows (wind-up poses, form colours, bat form).
bool rc_BossLook(const Enemy *e, uint16_t *shape, uint16_t *pal)
{
    switch(e->type)
    {
        case ET_GOLEM:
        {
            static const uint16_t kPal[4] = { PT_GOLEM_EARTH, PT_GOLEM_FIRE, PT_GOLEM_ICE, PT_GOLEM_STORM };
            *pal = kPal[e->cnt & 3u];
            if(e->st == 1u)
                *shape = (e->aux2 == GA_DASH) ? SH_GOLEM_C : (e->aux2 == GA_SLAM || e->aux2 == GA_SEAL) ? SH_GOLEM_B : SH_GOLEM_D;
            return true;
        }
        case ET_EYEKING:
            if(e->st == 1u) *pal = (e->aux2 == 0u) ? PT_EYEKING_FIRE : (e->aux2 == 1u) ? PT_EYEKING_NULL : PT_EYEKING_GRAV;
            return true;
        case ET_VAMPIRE:
            if(e->st == VL_BAT) { *shape = SH_BAT; *pal = PT_BAT; }
            else if(e->st == 1u && (e->tm & 4u)) *pal = PT_ORB_BLOOD;
            return true;
        case ET_LICH:
            if(e->st == 1u || e->st == 2u) *shape = SH_LICH_B;
            return true;
        default:
            return false;
    }
}


bool rc_Untargetable(const Enemy *e)
{
    return (e->type == ET_GHOST && e->st == 1u) || (e->type == ET_SLIMEKING && e->st == SK_HIDDEN) ||
           (e->type == ET_DRAGON && DragonAloft(e));
}


// Per tick: floor marks fade, and the Earth seal crumbles (cracking near the end).
void rc_BossTick(void)
{
    uint16_t i, n = 0;

    for(i = 0; i < rc_nMark; i++)
        if(rc_mark[i].life && --rc_mark[i].life) rc_mark[n++] = rc_mark[i];
    rc_nMark = n;

    if(s_nSeal)
    {
        if(--s_sealT == 0u || rc_playerRoom != s_sealRoom || rc_CountType(ET_GOLEM) == 0u) BreakSeal();
        else if(s_sealT < 60u && (s_sealT & 7u) == 0u)  // cracking: the walls flicker before they fall
        {
            for(i = 0; i < s_nSeal; i++) rc_tile[s_seal[i]] = (rc_tile[s_seal[i]] == TILE_EARTH) ? 3u : TILE_EARTH;
            rc_viewDirty = 2;
        }
    }
}


void rc_OnBossDeath(const Enemy *e, int32_t x, int32_t y)
{
    if(e->type == ET_GOLEM) { BreakSeal(); rc_MarksClear(); }
    if(e->type == ET_LICH)                              // death blast after a big warning ring
    {
        rc_MakeWarn(x, y, 3000, 45, AR_NOVA, 1);
        rc_Sfx(&sfx_game_over);
    }
}


void rc_ResetBosses(void)
{
    rc_nMark = 0;
    s_nSeal = 0;
    s_sealT = 0;
}
